// Every fixture owns its SQLite database or PostgreSQL schema. The schema is
// generated by the real ent migration, not a mock SQL execution adapter.
func observedSchemaFixture(t *testing.T, name string) (*sql.DB, *ent.Client) {
	t.Helper()
	var db *sql.DB
	if name == "sqlite" {
		registered, err := sql.Open("sqlite", ":memory:")
		if err != nil {
			t.Fatal(err)
		}
		drv := registered.Driver()
		registered.Close()
		db = sql.OpenDB(ObserveConnector(registeredConnector{driver: drv, dsn: ":memory:?_pragma=foreign_keys(1)"}, dialect.SQLite))
		db.SetMaxOpenConns(1)
	} else {
		dsn := os.Getenv("LINGUAFLOW_TEST_POSTGRES_DSN")
		if dsn == "" {
			t.Skip("LINGUAFLOW_TEST_POSTGRES_DSN is not set")
		}
		cfg, err := pgx.ParseConfig(dsn)
		if err != nil {
			t.Fatal("invalid PostgreSQL test DSN")
		}
		admin := stdlib.OpenDB(*cfg)
		schema := fmt.Sprintf("persistence_review_%d", time.Now().UnixNano())
		if _, err := admin.ExecContext(t.Context(), "CREATE SCHEMA "+schema); err != nil {
			admin.Close()
			t.Fatal(err)
		}
		t.Cleanup(func() {
			_, err := admin.ExecContext(context.Background(), "DROP SCHEMA "+schema+" CASCADE")
			if err != nil {
				t.Error(err)
			}
			admin.Close()
		})
		cfg.RuntimeParams["search_path"] = schema
		cfg.RuntimeParams["timezone"] = "UTC"
		db = sql.OpenDB(ObserveConnector(stdlib.GetConnector(*cfg), dialect.Postgres))
		db.SetMaxOpenConns(3)
	}
	client := ent.NewClient(ent.Driver(NewDriver(entsql.OpenDB(DialectFor(name), db))))
	t.Cleanup(func() { client.Close() })
	if err := client.Schema.Create(t.Context()); err != nil {
		t.Fatal(err)
	}
	return db, client
}

func TestPublishedDataMigrationPlanAndHistory(t *testing.T) {
	for _, name := range []string{"sqlite", "postgres"} {
		t.Run(name, func(t *testing.T) {
			db, c := observedSchemaFixture(t, name)
			ctx := t.Context()
			// Reproduce exactly the two published JSON columns ent's append-only
			// schema creation must retain until conversion finishes.
			for _, column := range []string{"segment_ids", "resource_ids"} {
				if _, err := db.ExecContext(ctx, "ALTER TABLE sync_tasks ADD COLUMN "+column+" TEXT NOT NULL DEFAULT ''"); err != nil {
					t.Fatal(err)
				}
			}
			actor := c.User.Create().SetUsername("migration_actor").SaveX(ctx)
			project := c.Project.Create().SetName("published project").SetOwnerUserID(actor.ID).SaveX(ctx)
			res := c.Resource.Create().SetProjectID(project.ID).SetPath("old.txt").SetFormat("txt").SetStoragePath("old").SaveX(ctx)
			moved := c.Resource.Create().SetProjectID(project.ID).SetPath("moved.txt").SetFormat("txt").SetStoragePath("moved").SaveX(ctx)
			first := c.Segment.Create().SetResourceID(res.ID).SetSegmentIndex(0).SetSourceText("first").SaveX(ctx)
			second := c.Segment.Create().SetResourceID(moved.ID).SetSegmentIndex(0).SetSourceText("second").SaveX(ctx)
			entry := c.GlossaryEntry.Create().SetProjectID(project.ID).SetSourceKey("word").SetSource("word").SetTarget("old").SaveX(ctx)
			oldTime := time.Date(2026, 11, 15, 12, 0, 0, 123456000, time.UTC)
			result := fmt.Sprintf(`{"total_updated":1,"total_skipped":0,"resources":[{"resource_id":%d,"resource_path":"old.txt","updated_count":1,"skipped_count":0}]}`, res.ID)
			create := func(status, ids, resources, result string, cp, next int) *ent.SyncTask {
				task := c.SyncTask.Create().SetProjectID(project.ID).SetEntryID(entry.ID).SetActorUserID(actor.ID).SetOldTarget("old").SetNewTarget("new").SetTotalSegments(3).SetProcessedSegments(next).SetNextSegmentIndex(next).SetCheckpointVersion(cp).SetStatus(status).SetResult(result).SetCreatedAt(oldTime).SetUpdatedAt(oldTime).SaveX(ctx)
				if _, err := c.ExecContext(ctx, "UPDATE sync_tasks SET segment_ids=$1,resource_ids=$2 WHERE id=$3", ids, resources, task.ID); err != nil {
					t.Fatal(err)
				}
				return task
			}
			ids := fmt.Sprintf("[%d,%d,999999]", first.ID, second.ID)
			resources := fmt.Sprintf("[%d]", res.ID)
			running := create("running", ids, resources, result, 1, 1)
			terminal := create("completed", ids, resources, result, 1, 1)
			legacy := create("pending", ids, "invalid legacy resources", "", 0, 0)
			invalid := create("running", fmt.Sprintf("[%d,%d,999999]", first.ID, first.ID), resources, result, 1, 1)
			if err := MigratePublishedData(ctx, c, name); err != nil {
				t.Fatal(err)
			}
			if err := MigratePublishedData(ctx, c, name); err != nil {
				t.Fatal("idempotent", err)
			}
			if err := CheckPublishedDataFormat(ctx, db, name, false); err != nil {
				t.Fatal(err)
			}
			cols, err := publishedColumns(ctx, db, name, "sync_tasks")
			if err != nil || cols["segment_ids"] || cols["resource_ids"] {
				t.Fatalf("legacy columns remain: %v %v", cols, err)
			}
			actual := c.SyncTask.GetX(ctx, running.ID)
			if actual.CheckpointVersion != 2 || actual.NextSegmentIndex != 1 || actual.ProcessedSegments != 1 || actual.TotalUpdated != 1 || actual.TotalSkipped != 0 || actual.Status != "running" || actual.Result != "" || !actual.UpdatedAt.Equal(oldTime) {
				t.Fatalf("running checkpoint changed: %+v", actual)
			}
			rows, err := db.QueryContext(ctx, "SELECT ordinal,segment_id,resource_id FROM sync_task_items WHERE task_id=$1 ORDER BY ordinal", running.ID)
			if err != nil {
				t.Fatal(err)
			}
			count := 0
			for rows.Next() {
				var ordinal, id, resource int
				if err := rows.Scan(&ordinal, &id, &resource); err != nil {
					t.Fatal(err)
				}
				wantResource := 0
				if count == 0 {
					wantResource = res.ID
				}
				if ordinal != count || resource != wantResource {
					t.Fatalf("plan=%d/%d/%d", ordinal, id, resource)
				}
				count++
			}
			if err := errors.Join(rows.Err(), rows.Close()); err != nil {
				t.Fatal(err)
			}
			if count != 3 {
				t.Fatal("deleted position lost", count)
			}
			history := c.SyncTask.GetX(ctx, terminal.ID)
			if history.Result != result || history.Status != "completed" || !history.UpdatedAt.Equal(oldTime) || history.FinishedAt != nil || history.CheckpointVersion != 1 {
				t.Fatalf("terminal history changed: %+v", history)
			}
			if c.SyncTask.GetX(ctx, legacy.ID).CheckpointVersion != 2 {
				t.Fatal("safe unstarted legacy task did not migrate")
			}
			failed := c.SyncTask.GetX(ctx, invalid.ID)
			if failed.Status != "failed" || failed.Result != result || failed.FinishedAt == nil {
				t.Fatal("untrusted progress was replayed or discarded")
			}
			if c.SyncTaskItem.Query().CountX(ctx) != 6 {
				t.Fatal("terminal/untrusted plans expanded")
			}
		})
	}
}

func TestPublishedDataMigrationRollsBackBeforeDroppingPlan(t *testing.T) {
	for _, name := range []string{"sqlite", "postgres"} {
		t.Run(name, func(t *testing.T) {
			db, c := observedSchemaFixture(t, name)
			ctx := t.Context()
			// A invalid already-persisted evidence is never silently cleared.
			if _, err := db.ExecContext(ctx, "ALTER TABLE sync_tasks ADD COLUMN segment_ids TEXT NOT NULL DEFAULT '[7]'"); err != nil {
				t.Fatal(err)
			}
			if _, err := db.ExecContext(ctx, "ALTER TABLE sync_tasks ADD COLUMN resource_ids TEXT NOT NULL DEFAULT '[8]'"); err != nil {
				t.Fatal(err)
			}
			if _, err := db.ExecContext(ctx, "CREATE TABLE preserved_evidence (id INTEGER)"); err != nil {
				t.Fatal(err)
			}
			// Test the decoder directly on minimal typed storage to avoid inventing
			// invalid identity relationships in the generated account schema.
			if _, err := db.ExecContext(ctx, "ALTER TABLE login_bindings RENAME TO valid_login_bindings"); err != nil {
				t.Fatal(err)
			}
			if _, err := db.ExecContext(ctx, "CREATE TABLE login_bindings (id INTEGER PRIMARY KEY,evidence TEXT,evidence_expires_at "+map[bool]string{true: "timestamptz", false: "datetime"}[name == "postgres"]+")"); err != nil {
				t.Fatal(err)
			}
			if _, err := db.ExecContext(ctx, "INSERT INTO login_bindings(id,evidence) VALUES(1,$1)", `{"expires_at":"invalid"}`); err != nil {
				t.Fatal(err)
			}
			if err := MigratePublishedData(ctx, c, name); err == nil {
				t.Fatal("invalid evidence silently migrated")
			}
			cols, err := publishedColumns(ctx, db, name, "sync_tasks")
			if err != nil || !cols["segment_ids"] || !cols["resource_ids"] {
				t.Fatal("unique old plan dropped after failure", err)
			}
			format, err := publishedColumns(ctx, db, name, persistenceFormatTable)
			if err != nil || len(format) != 0 {
				t.Fatal("format committed after failed conversion", err)
			}
			var evidence string
			if err := db.QueryRowContext(ctx, "SELECT evidence FROM login_bindings WHERE id=1").Scan(&evidence); err != nil || evidence != `{"expires_at":"invalid"}` {
				t.Fatal("invalid evidence lost", err)
			}
		})
	}
}

func TestPublishedDataMigrationLateFailureKeepsCheckpointForRetry(t *testing.T) {
	for _, driver := range []string{"sqlite", "postgres"} {
		t.Run(driver, func(t *testing.T) {
			db, c := observedSchemaFixture(t, driver)
			ctx := t.Context()
			for _, column := range []string{"segment_ids", "resource_ids"} {
				if _, err := db.ExecContext(ctx, "ALTER TABLE sync_tasks ADD COLUMN "+column+" TEXT NOT NULL DEFAULT ''"); err != nil {
					t.Fatal(err)
				}
			}
			actor := c.User.Create().SetUsername("late_failure_actor").SaveX(ctx)
			project := c.Project.Create().SetName("late failure").SetOwnerUserID(actor.ID).SaveX(ctx)
			resource := c.Resource.Create().SetProjectID(project.ID).SetPath("original.txt").SetFormat("txt").SetStoragePath("original").SaveX(ctx)
			segment := c.Segment.Create().SetResourceID(resource.ID).SetSegmentIndex(0).SetSourceText("original").SetTargetText("committed translation").SaveX(ctx)
			entry := c.GlossaryEntry.Create().SetProjectID(project.ID).SetSourceKey("original").SetSource("original").SetTarget("new").SaveX(ctx)
			stored := fmt.Sprintf(`{"total_updated":1,"total_skipped":0,"resources":[{"resource_id":%d,"resource_path":"original.txt","updated_count":1,"skipped_count":0}]}`, resource.ID)
			tasks := make([]*ent.SyncTask, 0, 2)
			at := time.Date(2026, 11, 22, 12, 34, 56, 123456000, time.UTC)
			for range 2 {
				task := c.SyncTask.Create().SetProjectID(project.ID).SetEntryID(entry.ID).SetActorUserID(actor.ID).SetOldTarget("old").SetNewTarget("new").SetTotalSegments(2).SetProcessedSegments(1).SetNextSegmentIndex(1).SetCheckpointVersion(1).SetStatus("running").SetResult(stored).SetCreatedAt(at).SetUpdatedAt(at).SaveX(ctx)
				if _, err := db.ExecContext(ctx, "UPDATE sync_tasks SET segment_ids=$1,resource_ids=$2 WHERE id=$3", fmt.Sprintf("[%d,999999]", segment.ID), fmt.Sprintf("[%d]", resource.ID), task.ID); err != nil {
					t.Fatal(err)
				}
				tasks = append(tasks, task)
			}
			// Force the second task's INSERT to fail after the first task has
			// already copied children and cleared its active serialized result.
			conflict := c.SyncTaskItem.Create().SetTaskID(tasks[1].ID).SetOrdinal(0).SetSegmentID(segment.ID).SetResourceID(resource.ID).SaveX(ctx)
			if err := MigratePublishedData(ctx, c, driver); err == nil {
				t.Fatal("injected child uniqueness failure was accepted")
			}
			for _, task := range tasks {
				actual := c.SyncTask.GetX(ctx, task.ID)
				if actual.CheckpointVersion != 1 || actual.NextSegmentIndex != 1 || actual.TotalUpdated != 0 || actual.Result != stored || !actual.UpdatedAt.Equal(task.UpdatedAt) {
					t.Fatalf("failed transaction changed published checkpoint: %+v", actual)
				}
			}
			if c.SyncTaskItem.Query().CountX(ctx) != 1 || c.SyncTaskResult.Query().CountX(ctx) != 0 {
				t.Fatal("failed transaction retained newly copied facts")
			}
			columns, err := publishedColumns(ctx, db, driver, "sync_tasks")
			if err != nil || !columns["segment_ids"] || !columns["resource_ids"] {
				t.Fatal("failed transaction removed the unique source plans", err)
			}
			marker, err := publishedColumns(ctx, db, driver, persistenceFormatTable)
			if err != nil || len(marker) != 0 {
				t.Fatal("failed transaction published the format marker", err)
			}
			c.SyncTaskItem.DeleteOne(conflict).ExecX(ctx)
			if err := MigratePublishedData(ctx, c, driver); err != nil {
				t.Fatal("retry from intact source checkpoint", err)
			}
			if err := MigratePublishedData(ctx, c, driver); err != nil {
				t.Fatal("repeat successful conversion", err)
			}
			if c.SyncTaskItem.Query().CountX(ctx) != 4 || c.SyncTaskResult.Query().CountX(ctx) != 2 {
				t.Fatal("retry lost or duplicated checkpoint facts")
			}
			for _, task := range tasks {
				actual := c.SyncTask.GetX(ctx, task.ID)
				if actual.CheckpointVersion != 2 || actual.TotalUpdated != 1 || actual.Result != "" {
					t.Fatal("retry did not restore the final active checkpoint")
				}
			}
			if got := c.Segment.GetX(ctx, segment.ID).TargetText; got == nil || *got != "committed translation" {
				t.Fatal("failed conversion or retry changed committed translation")
			}
		})
	}
}

func TestPublishedDataFormatRejectsFutureBeforeSchemaWrite(t *testing.T) {
	for _, name := range []string{"sqlite", "postgres"} {
		t.Run(name, func(t *testing.T) {
			db, c := observedSchemaFixture(t, name)
			ctx := t.Context()
			if _, err := db.ExecContext(ctx, persistenceMarkerDDL); err != nil {
				t.Fatal(err)
			}
			if _, err := db.ExecContext(ctx, "INSERT INTO "+persistenceFormatTable+" VALUES(1,2)"); err != nil {
				t.Fatal(err)
			}
			for _, auto := range []bool{false, true} {
				if err := CheckPublishedDataFormat(ctx, db, name, auto); !errors.Is(err, ErrPersistenceFormatUnsupported) {
					t.Fatal("future accepted", err)
				}
			}
			if err := MigratePublishedData(ctx, c, name); !errors.Is(err, ErrPersistenceFormatUnsupported) {
				t.Fatal("future conversion accepted", err)
			}
			var version int
			if err := db.QueryRowContext(ctx, "SELECT version FROM "+persistenceFormatTable).Scan(&version); err != nil || version != 2 {
				t.Fatal("future marker changed", err)
			}
		})
	}
}

func TestPublishedDataMigrationRejectsMissingActivePlan(t *testing.T) {
	for _, driver := range []string{"sqlite", "postgres"} {
		t.Run(driver, func(t *testing.T) {
			db, c := observedSchemaFixture(t, driver)
			ctx := t.Context()
			actor := c.User.Create().SetUsername("missing_plan_actor").SaveX(ctx)
			project := c.Project.Create().SetName("missing plan").SetOwnerUserID(actor.ID).SaveX(ctx)
			entry := c.GlossaryEntry.Create().SetProjectID(project.ID).SetSourceKey("original").SetSource("original").SetTarget("new").SaveX(ctx)
			stored := `{"total_updated":1,"total_skipped":0,"resources":[]}`
			task := c.SyncTask.Create().SetProjectID(project.ID).SetEntryID(entry.ID).SetActorUserID(actor.ID).SetOldTarget("old").SetNewTarget("new").SetTotalSegments(2).SetProcessedSegments(1).SetNextSegmentIndex(1).SetCheckpointVersion(1).SetStatus("running").SetResult(stored).SaveX(ctx)
			if err := MigratePublishedData(ctx, c, driver); err == nil {
				t.Fatal("missing unique active plan received a format marker")
			}
			marker, err := publishedColumns(ctx, db, driver, persistenceFormatTable)
			if err != nil || len(marker) != 0 {
				t.Fatal("incomplete plan committed its migration marker", err)
			}
			actual := c.SyncTask.GetX(ctx, task.ID)
			if actual.CheckpointVersion != 1 || actual.Result != stored || actual.Status != "running" {
				t.Fatal("missing plan refusal replaced the original checkpoint facts")
			}
		})
	}
}

func TestPublishedBindingExpiryPrecision(t *testing.T) {
	for _, name := range []string{"sqlite", "postgres"} {
		t.Run(name, func(t *testing.T) {
			db, c := observedSchemaFixture(t, name)
			ctx := t.Context()
			if _, err := db.ExecContext(ctx, "ALTER TABLE login_bindings RENAME TO valid_login_bindings"); err != nil {
				t.Fatal(err)
			}
			if _, err := db.ExecContext(ctx, "CREATE TABLE login_bindings (id INTEGER PRIMARY KEY,evidence TEXT,evidence_expires_at "+map[bool]string{true: "timestamptz", false: "datetime"}[name == "postgres"]+")"); err != nil {
				t.Fatal(err)
			}
			expiry := time.Date(2026, 11, 22, 12, 34, 56, 123456789, time.FixedZone("offset", 8*3600))
			if _, err := db.ExecContext(ctx, "INSERT INTO login_bindings VALUES(1,$1,NULL),(2,'null',NULL),(3,'{}',NULL)", fmt.Sprintf(`{"expires_at":%q}`, expiry.Format(time.RFC3339Nano))); err != nil {
				t.Fatal(err)
			}
			if err := MigratePublishedData(ctx, c, name); err != nil {
				t.Fatal(err)
			}
			var actual time.Time
			if err := db.QueryRowContext(ctx, "SELECT evidence_expires_at FROM login_bindings WHERE id=1").Scan(&actual); err != nil {
				t.Fatal(err)
			}
			want := expiry.UTC()
			if name == "postgres" {
				want = timeutil.CeilMicrosecond(want)
			}
			if !actual.Equal(want) {
				t.Fatalf("expiry=%v want=%v", actual, want)
			}
			var absent int
			if err := db.QueryRowContext(ctx, "SELECT COUNT(*) FROM login_bindings WHERE evidence_expires_at IS NULL").Scan(&absent); err != nil || absent != 2 {
				t.Fatal("zero/null expired", err)
			}
		})
	}
}
